import math, itertools

def cube_face_graph_edges():
    # Faces of a cube correspond to vertices of an octahedron; adjacency is every pair except opposites.
    # Label six faces as +x(0), -x(1), +y(2), -y(3), +z(4), -z(5).
    opp = {(0,1), (2,3), (4,5)}
    edges = []
    for i in range(6):
        for j in range(i+1, 6):
            if (i,j) not in opp and (j,i) not in opp:
                edges.append((i,j))
    return edges

def octahedron_face_graph_edges():
    # Faces of an octahedron correspond to vertices of a cube; use 3-bit labels 0..7.
    edges = []
    for i in range(8):
        for bit in range(3):
            j = i ^ (1 << bit)
            if i < j:
                edges.append((i, j))
    return edges

